/**
 * Writes a notion_output envelope to stdout using the shared wire format.
 * The platform runner scans a run's log stream for this envelope to
 * recover the capability's result.
 */
export function writeOutput(value: unknown): void {
	process.stdout.write(`\n<__notion_output__>${JSON.stringify(value)}</__notion_output__>\n`);
}

/**
 * Writes the value caught by a Worker execution boundary to a dedicated tag.
 * A run has one execution boundary, so this must be called at most once per run.
 */
export function writeError(value: unknown): void {
	process.stdout.write(
		`\n<__notion_error__>${escapeErrorTagValue(stringifyErrorValue(value))}</__notion_error__>\n`,
	);
}

function serializeError(
	value: Error,
	seenErrors = new Set<Error>(),
): {
	name: string;
	message: string;
	stacktrace?: string;
	cause?: unknown;
} {
	seenErrors.add(value);
	const serializedError = {
		name: value.name,
		message: value.message,
		...(value.stack !== undefined ? { stacktrace: value.stack } : {}),
		...(value.cause !== undefined ? { cause: serializeErrorValue(value.cause, seenErrors) } : {}),
	};
	seenErrors.delete(value);
	return serializedError;
}

function serializeErrorValue(value: unknown, seenErrors = new Set<Error>()): unknown {
	if (!(value instanceof Error)) {
		return value;
	}
	return seenErrors.has(value) ? "[Circular Error]" : serializeError(value, seenErrors);
}

function stringifyErrorValue(value: unknown): string {
	return String(JSON.stringify(serializeErrorValue(value)));
}

function escapeErrorTagValue(value: string): string {
	return value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;");
}
